  AS x(id uuid, name text, industry text, description text, aliases text[], domain text, featured boolean, slug text, created_at timestamp)
WHERE NOT EXISTS (SELECT 1 FROM companies c WHERE c.id = x.id OR c.name = x.name OR (x.slug IS NOT NULL AND c.slug = x.slug));

