  AS x(id uuid, company_id uuid, company_name text, name text, specialization text, description text, latitude text, longitude text, state text,
       workforce_size integer, open_positions integer, primary_naics varchar, primary_naics_description text, source_count integer,
       confidence integer, address text, city text, zip_code varchar, country text, created_at timestamp)
JOIN LATERAL (
  SELECT c.id FROM companies c WHERE c.id = x.company_id OR c.name = x.company_name ORDER BY (c.id = x.company_id) DESC LIMIT 1
) c ON true
WHERE NOT EXISTS (SELECT 1 FROM factories f WHERE f.id = x.id);

